WITH valid AS (SELECT id, customer_id, store_id, amount, discount, shipping_fee, amount - shipping_fee AS amount_with_shipping FROM orders WHERE store_id IS NULL) SELECT customer_id, store_id, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS cnt, PERCENTILE_APPROX(amount_with_shipping, 0.9) AS amount_with_shipping_p90 FROM valid GROUP BY customer_id, store_id HAVING COUNT(*) > 1 ORDER BY cnt;
